begin;
create table if not exists workshop_private.seeds89(key text primary key);
alter table workshop_private.seeds89 enable row level security;
revoke all on workshop_private.seeds89 from public,anon,authenticated;
do $$ begin
 if exists(select 1 from workshop_private.seeds89 where key='hygiene-pdfs') then return;end if;
 perform 1 from workshop_private.catalog75_rev where section='Hygiène, protection et nettoyage' for update;
 if not found then raise exception 'Exécute d’abord le script 89a';end if;
update workshop_private.catalog75_rev set rev=rev+1 where section='Hygiène, protection et nettoyage';
notify pgrst,'reload schema';commit;
